    "FROM batch_page bp JOIN archive_page ap ON ap.id = bp.page_id WHERE bp.request_id = ?", requestId);
if (!existing.isEmpty()) {
    row = existing.get(0);
    if (batchId == ((Number)row.get("batch_id")).longValue() && collectionNo.equals(row.get("collection_no")))
        return new EnrollResponse(id, batchId, pageId, status, true);
    throw new ApiException(CONFLICT, "REQUEST_ID_CONFLICT", "requestId 已被不同参数使用");
}
Map batch = lockBatch(batchId);
if (!"OPEN".equals(batch.get("status"))) throw 409 BATCH_NOT_OPEN;
Long pageId = query page by collection_no → 404 PAGE_NOT_FOUND;
long batchPageId;
try {
    jdbc.update("INSERT INTO batch_page(batch_id, page_id, request_id, status) VALUES (?,?,?,'ACTIVE')", batchId, pageId, requestId);
} catch (DuplicateKeyException e) {
    // 并发同键：重读并比较
    ... re-query; if same params return replayed else 409
}
batchPageId = query id by request_id;
try {
    jdbc.update("INSERT INTO page_occupancy(page_id, batch_id, batch_page_id) VALUES (?,?,?)", ...);
} catch (DuplicateKeyException e) {
    throw new ApiException(CONFLICT, "PAGE_OCCUPIED", "档案页已处于进行中的处理批次: " + collectionNo);
}
return new EnrollResponse(batchPageId, batchId, pageId, "ACTIVE", false);
